<template>
  <div v-if="session.player || session.task && !terminal || session.reconnectable || session.error && !session.open" class="qvoice-dock" role="region" :aria-label="vt(&quot;语音工作区&quot;)">
    <div class="qvoice-mini-orb" :class="{ active:session.playing || session.busy }" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div>
    <div class="qvoice-dock-copy"><strong>{{ session.player ? `${vt(voiceName(session.task?.voice))} · ${vt(session.player.title)}` : vt("声音工作区") }}</strong><span role="status">{{ vt(session.error) || vt(session.playbackNotice) || (session.player?vt(voicePlaybackLabel(session.playbackPhase,session.task)):vt(voiceTaskLabel(session.task))) || vt("正在连接…") }}</span></div>
    <button v-if="session.player" type="button" class="qvoice-circle" :disabled="session.canceling" :aria-label="session.playbackRequested?vt(&quot;暂停朗读&quot;):vt(&quot;播放朗读&quot;)" @click="session.play"><ClientIcon :name="session.playbackRequested?'pause':'play'" />{{ session.playbackRequested?'Ⅱ':'▶' }}</button>
    <span v-if="session.player" class="qvoice-time">{{ voiceDuration(session.playbackSeconds) }}<small v-if="session.playbackMode!=='stream'&&session.task.audio?.length>1">{{ session.audioPart+1 }}/{{ session.task.audio.length }}</small></span>
    <button v-if="session.playbackReconnectable" type="button" class="qvoice-text-button" :disabled="session.canceling" @click="session.reconnectPlayback">{{ vt("重新连接播放") }}</button><button v-if="session.reconnectable" type="button" class="qvoice-text-button" :disabled="session.busy" @click="session.resubmittable?session.resubmit():session.reconnect()">{{ session.resubmittable?vt("继续本次提交"):vt("重新连接") }}</button>
    <button v-if="session.task && !terminal" type="button" class="qvoice-text-button" :disabled="session.canceling||session.task.status==='SETTLING'" @click="session.cancelTask">{{ session.canceling?vt("正在停止…"):vt("停止生成") }}</button>
    <button type="button" class="qvoice-text-button" @click="session.show('voices')">{{ vt("音色") }}</button>
    <button v-if="session.player" type="button" class="qvoice-close" :aria-label="vt(&quot;收起朗读&quot;)" @click="session.stopPlayback();session.player=null">×</button>
  </div>
  <el-dialog :model-value="session.open" :title="vt(&quot;声音工作区&quot;)" class="qvoice-dialog" width="760px" align-center append-to-body destroy-on-close :close-on-click-modal="false" :before-close="session.close" @update:model-value="value=>{if(!value)session.close()}">
    <template #header><div class="qvoice-eyebrow"><span></span> QGAUSS VOICE STUDIO</div></template>
    <div class="qvoice-studio">
      <div class="qvoice-topline"><div><h2>{{ vt("把灵感，说出来") }}<span>{{ vt("。") }}</span></h2><p>{{ vt("说给 QGauss，或者，让好答案拥有声音。") }}</p></div><div class="qvoice-orb" :class="{ active:session.recording || session.playing }" :style="{ '--voice-level':session.level }" aria-hidden="true"><i></i><i></i><span>Q</span></div></div>
      <div v-if="!session.confirmation" class="qvoice-tabs" role="tablist" :aria-label="vt(&quot;语音功能&quot;)"><button type="button" role="tab" :aria-selected="session.tab==='record'" :class="{active:session.tab==='record'}" @click="session.tab='record'">{{ vt("语音输入") }}</button><button type="button" role="tab" :aria-selected="session.tab==='voices'" :class="{active:session.tab==='voices'}" @click="session.tab='voices'">{{ vt("声音偏好") }}</button></div>
      <div v-if="session.loading" class="qvoice-loading" role="status"><QLoader text="" :size="28" />{{ vt("正在准备声音工作区…") }}</div>
      <div v-else-if="session.confirmation" class="qvoice-confirm">
        <div class="qvoice-confirm-icon" aria-hidden="true">✦</div><h3>{{ vt("声音即将出发") }}</h3><p>{{ session.confirmation.quote.kind==='transcription'?vt("这段录音将发送给语音服务，转好后由你确认文字。"):vt("所选文字将发送给语音服务，生成 AI 合成音频。") }}</p>
        <strong>{{ voiceCharge(session.confirmation.quote,vt) }}</strong><small v-if="session.confirmation.quote.segments>1">{{ vt("长回答将分为 {p0} 段连续播放，以上为整次费用。",{p0:session.confirmation.quote.segments}) }}</small><small>{{ vt("先预留次数，完整完成后结算；失败或停止会退回可用次数。") }}</small>
        <div class="qvoice-buttons"><button type="button" class="qvoice-secondary" @click="session.cancelConfirmation">{{ vt("再想一下") }}</button><button type="button" class="qvoice-primary" @click="session.confirm">{{ vt("确认并开始") }} <span>↗</span></button></div>
      </div>
      <div v-else-if="session.tab==='record'" class="qvoice-record-panel">
        <div v-if="!session.options?.transcription?.ready" class="qvoice-unavailable"><ClientIcon name="microphone" /><strong>{{ vt("录音转写还在准备中") }}</strong><p>{{ vt(session.options?.transcription?.reason) || vt("管理员接入语音服务后，就能在这里录音转文字。") }}</p><button type="button" class="qvoice-text-button" :disabled="session.busy" @click="session.loadOptions">{{ vt("刷新状态") }}</button></div>
        <template v-else>
          <div class="qvoice-record-stage" :class="{recording:session.recording}"><div class="qvoice-wave" :style="{'--voice-level':session.level}" aria-hidden="true"><i v-for="index in 33" :key="index" :style="{'--wave-index':index,'--bar-size':`${12+Math.sin(index*1.8)**2*35}px`}"></i></div><strong>{{ session.recording?vt("我在听，慢慢说"):session.hasRecording?vt("这一段，已经留好"):session.requestingMic?vt("等待麦克风许可…"):vt("给灵感一个麦克风") }}</strong><p>{{ session.recording?vt("录音暂存在当前页面，结束后再确认转写。"):session.hasRecording?vt("可以先听一遍，再转成文字。"):vt("录音不会直接发送为消息；转写后由你确认。") }}</p><span class="qvoice-record-time">{{ voiceDuration(session.seconds) }}<small> / {{ voiceDuration(session.options.maxRecordingSeconds || 300) }}</small></span></div>
          <audio v-if="session.recordingUrl" :src="session.recordingUrl" controls preload="metadata" class="qvoice-record-audio" :aria-label="vt(&quot;录音试听&quot;)"></audio>
          <div class="qvoice-buttons"><button v-if="session.recording" type="button" class="qvoice-record-stop" @click="session.finishRecording"><i></i>{{ vt("结束录音") }}</button><button v-else-if="!session.hasRecording" type="button" class="qvoice-primary" :disabled="session.busy || session.requestingMic || disabled" @click="session.record"><ClientIcon name="microphone" />{{ session.requestingMic?vt("正在申请…"):vt("开始录音") }}</button><button v-if="session.recording || session.requestingMic" type="button" class="qvoice-secondary" @click="session.clearRecording">{{ vt("取消录音") }}</button><template v-else-if="session.hasRecording"><button type="button" class="qvoice-secondary" :disabled="session.busy || session.reconnectable" @click="session.clearRecording">{{ vt("重新录制") }}</button><button type="button" class="qvoice-primary" :disabled="session.busy || session.reconnectable || disabled" @click="session.transcribe">{{ session.busy?vt("正在处理…"):vt("转成文字") }} <span>↗</span></button></template></div>
          <p class="qvoice-cost">{{ vt("{p0} · 仅在确认转写时发送录音",{p0:voiceCharge(session.options.transcription,vt)}) }}</p><p v-if="session.options.retention" class="qvoice-cost">{{ vt("上传后若未提交转写，录音最多保留 {p0} 小时。已接受的任务按作品规则保存。",{p0:session.options.retention.pendingRecordingHours}) }}</p>
        </template>
        <div v-if="session.transcript" class="qvoice-transcript"><label for="qvoice-transcript">{{ vt("听到这些，确认一下？") }}</label><textarea id="qvoice-transcript" v-model="session.transcript" rows="4" maxlength="30000" :aria-label="vt(&quot;转写文字&quot;)"></textarea><button type="button" class="qvoice-primary" :disabled="!session.transcript.trim() || disabled" @click="session.useTranscript">{{ vt("放入输入框") }} <span>↗</span></button><small>{{ vt("你可以继续编辑，再亲自点击发送。") }}</small></div>
      </div>
      <div v-else class="qvoice-voices-panel"><div class="qvoice-voice-grid"><button v-for="voice in VOICES" :key="voice.id" type="button" class="qvoice-voice" :class="{selected:session.voice===voice.id}" :style="{'--voice-color':voice.color}" :aria-label="vt(&quot;选择{p0} {p1}音色&quot;,{p0:vt(voice.name),p1:voice.label})" :aria-pressed="session.voice===voice.id" @click="session.setVoice(voice.id)"><span class="qvoice-voice-gem" aria-hidden="true">{{ voice.label[0] }}</span><span><strong>{{ vt(voice.name) }}<small>{{ voice.label }}</small></strong><span>{{ vt(voice.mood) }}</span></span><b v-if="session.voice===voice.id" aria-hidden="true">✓</b></button></div><div class="qvoice-audition"><p>{{ vt(VOICES.find(voice=>voice.id===session.voice)?.note) }}</p><button type="button" class="qvoice-secondary" :disabled="!session.options?.speech?.ready || session.busy || session.reconnectable || disabled" @click="session.preview">{{ session.busy?vt("声音准备中…"):vt("听听这个声音") }} <span>▷</span></button><small>{{ vt("{p0} · 每次试听会生成一段新音频",{p0:voiceCharge(session.options?.speech,vt)}) }}</small></div><label class="qvoice-auto"><span><strong>{{ vt("新回答自动朗读") }}</strong><small>{{ vt("只对本页新生成的回答生效；需要次数时仍先确认。") }}</small></span><input v-model="session.autoplay" type="checkbox" :disabled="!session.options?.speech?.ready" :aria-label="vt(&quot;新回答自动朗读&quot;)" /><span class="qvoice-switch" aria-hidden="true"></span></label><p v-if="!session.options?.speech?.ready" class="qvoice-cost">{{ vt(session.options?.speech?.reason) || vt("朗读服务尚未接入，选好的音色会为你保留。") }}</p></div>
      <p v-if="session.task && !terminal" class="qvoice-task-status" role="status"><QLoader text="" :size="17" />{{ vt(voiceTaskLabel(session.task)) }}<button type="button" class="qvoice-text-button" :disabled="session.task.status==='SETTLING'" @click="session.cancelTask">{{ vt("停止生成") }}</button></p>
      <div v-if="session.error" class="qvoice-error" role="alert">{{ vt(session.error) }}<button v-if="session.reconnectable" type="button" class="qvoice-text-button" :disabled="session.busy" @click="session.resubmittable?session.resubmit():session.reconnect()">{{ session.resubmittable?vt("继续本次提交"):vt("重新连接") }}</button></div>
      <footer><span>{{ vt("✧ AI 合成声音") }}</span><span>{{ vt("录音与文字只交给你确认使用的语音服务") }}</span></footer>
    </div>
  </el-dialog>
</template>
<script setup>
import {voiceText as vt} from "../../i18n/voice.js";
import { computed } from 'vue';
import { ElDialog } from 'element-plus';
import ClientIcon from '../reference/ClientIcon.vue';
import QLoader from '../QLoader.vue';
import { VOICES, voiceName, voiceDuration, voiceCharge, voiceTerminal, voiceTaskLabel,voicePlaybackLabel } from '../../lib/voice-presentation.js';
const props=defineProps({session:{type:Object,required:true},disabled:Boolean});
const terminal=computed(()=>voiceTerminal(props.session.task));
</script>
<style>
