.qvoice-buttons{display:flex;justify-content:center;gap:10px;margin:18px 0 10px}.qvoice-primary,.qvoice-secondary,.qvoice-record-stop{border:0;border-radius:13px;min-height:43px;padding:11px 20px;display:inline-flex;align-items:center;justify-content:center;gap:10px;cursor:pointer;font:inherit;font-size:12px;transition:transform .15s,box-shadow .15s}.qvoice-primary{background:linear-gradient(135deg,var(--qg-brand,#8173ec),color-mix(in srgb,var(--qg-brand,#8173ec) 70%,#f1adc3));color:white;box-shadow:0 7px 16px color-mix(in srgb,var(--qg-brand,#8173ec) 20%,transparent)}.qvoice-primary:hover:not(:disabled),.qvoice-secondary:hover:not(:disabled){transform:translateY(-2px)}.qvoice-primary:disabled,.qvoice-secondary:disabled,.qvoice-record-stop:disabled{opacity:.45;cursor:not-allowed}.qvoice-primary svg,.qvoice-secondary svg{width:16px;height:16px}.qvoice-secondary{color:var(--qg-text);background:color-mix(in srgb,var(--qg-brand,#8173ec) 8%,transparent);border:1px solid color-mix(in srgb,var(--qg-brand,#8173ec) 10%,transparent)}.qvoice-record-stop{color:#c36272;background:#e692a018}.qvoice-record-stop i{width:10px;height:10px;background:currentColor;border-radius:3px}.qvoice-cost{font-size:10px;color:var(--qg-sub);text-align:center;line-height:1.7;margin:8px 0 0}.qvoice-record-audio{display:block;width:100%;height:38px;margin-top:14px}
