.qvoice-transcript{margin-top:20px;padding:16px;border-radius:19px;background:color-mix(in srgb,var(--qg-brand,#8173ec) 6%,transparent)}.qvoice-transcript label{display:block;font-size:12px;font-weight:700;margin-bottom:9px}.qvoice-transcript textarea{width:100%;box-sizing:border-box;resize:vertical;border:1px solid color-mix(in srgb,var(--qg-brand,#8173ec) 20%,transparent);border-radius:12px;padding:12px;font:inherit;font-size:13px;line-height:1.8;color:inherit;background:var(--qg-card,#fff);margin-bottom:9px}.qvoice-transcript>small{display:block;color:var(--qg-sub);font-size:10px;margin-top:8px}.qvoice-task-status{display:flex;align-items:center;justify-content:center;gap:10px;font-size:12px;padding:12px;background:#9b9dd111;border-radius:12px;margin:14px 0 0}.qvoice-error{font-size:12px;line-height:1.7;background:#df899512;color:#c16c7a;padding:12px 14px;border-radius:13px;margin-top:14px;overflow-wrap:anywhere}.qvoice-studio footer{display:flex;justify-content:space-between;gap:12px;margin-top:22px;border-top:1px solid color-mix(in srgb,var(--qg-sub,#8a91a2) 12%,transparent);padding-top:13px;font-size:9px;line-height:1.6;color:var(--qg-sub)}.qvoice-unavailable{text-align:center;padding:40px 20px;border:1px dashed color-mix(in srgb,var(--qg-brand,#8173ec) 25%,transparent);border-radius:22px}.qvoice-unavailable>svg{display:block;margin:0 auto 14px;width:28px;height:28px;color:var(--qg-brand)}.qvoice-unavailable strong{font-size:15px}.qvoice-unavailable p{font-size:12px;color:var(--qg-sub);line-height:1.7}.qvoice-loading{min-height:230px;display:flex;align-items:center;justify-content:center;gap:12px;font-size:12px;color:var(--qg-sub)}.qvoice-text-button,.qvoice-close{border:0;background:transparent;color:var(--qg-sub);font:inherit;font-size:11px;cursor:pointer;padding:6px;white-space:nowrap}.qvoice-text-button:disabled{opacity:.45;cursor:wait}.qvoice-close{font-size:22px;line-height:1}.qvoice-confirm{text-align:center;padding:14px 22px}.qvoice-confirm-icon{margin:0 auto;width:55px;height:55px;border-radius:19px;display:grid;place-items:center;font-size:28px;color:var(--qg-brand);background:color-mix(in srgb,var(--qg-brand,#8173ec) 10%,transparent)}.qvoice-confirm h3{font-size:21px;margin:17px 0 10px}.qvoice-confirm p{font-size:12px;line-height:1.9;color:var(--qg-sub)}.qvoice-confirm>strong{display:block;font-size:17px;margin:18px 0 10px}.qvoice-confirm>small{display:block;font-size:10px;line-height:1.8;color:var(--qg-sub)}
.qvoice-dock{display:flex;align-items:center;gap:10px;max-width:900px;margin:0 auto 10px;padding:11px 14px;border-radius:19px;background:color-mix(in srgb,var(--qg-card,#fff) 85%,transparent);border:1px solid color-mix(in srgb,var(--qg-brand,#8173ec) 16%,transparent);box-shadow:0 5px 25px #8379bf12;backdrop-filter:blur(24px)}.qvoice-dock-copy{flex:1;min-width:0}.qvoice-dock-copy strong{display:block;font-size:11px;font-weight:650;line-height:1.6}.qvoice-dock-copy>span{display:block;color:var(--qg-sub);font-size:10px;line-height:1.6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.qvoice-mini-orb{display:flex;align-items:center;gap:2px;justify-content:center;flex-shrink:0;width:35px;height:35px;border-radius:12px;background:linear-gradient(140deg,#d4e6ed,#c4b7e8,#e7c5d7);box-shadow:inset 2px 2px 5px #ffffffb0,inset -2px -3px 7px #8173b521}.qvoice-mini-orb i{width:2px;height:13px;border-radius:2px;background:#fff;box-shadow:0 1px 3px #8173b530}.qvoice-mini-orb i:nth-child(2n){height:20px}.qvoice-mini-orb i:nth-child(3){height:26px}.qvoice-mini-orb.active i{animation:qvoice-mini 1.1s ease-in-out infinite}.qvoice-mini-orb.active i:nth-child(2n){animation-delay:-.4s}.qvoice-circle{display:grid;place-items:center;flex-shrink:0;width:29px;height:29px;border:1px solid color-mix(in srgb,var(--qg-brand,#8173ec) 15%,transparent);border-radius:50%;color:var(--qg-brand);background:color-mix(in srgb,var(--qg-brand,#8173ec) 6%,transparent);cursor:pointer;font-size:11px}.qvoice-circle svg{display:none}.qvoice-time{font-size:10px;color:var(--qg-sub);font-variant-numeric:tabular-nums}.qvoice-time small{display:block;font-size:9px;text-align:center}
.qvoice-dialog.el-dialog{overflow-x:hidden}.qvoice-orb{margin-right:17px}.qvoice-dialog .el-dialog__headerbtn{z-index:2}
@keyframes qvoice-float{50%{transform:translateY(-5px) rotate(-5deg);border-radius:46% 39% 45% 40%}}@keyframes qvoice-wave{50%{transform:scaleY(calc(.55 + var(--voice-level)*.9))}}@keyframes qvoice-mini{50%{transform:scaleY(.4)}}
@media(max-width:600px){.qvoice-dialog.el-dialog{padding:22px 17px;border-radius:24px}.qvoice-topline h2{font-size:23px}.qvoice-topline p{font-size:10px}.qvoice-orb{width:62px;height:62px}.qvoice-orb span{font-size:25px}.qvoice-topline{padding:23px 2px}.qvoice-voice-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.qvoice-voice{padding:12px 9px;gap:9px;border-radius:15px}.qvoice-voice-gem{width:32px;height:36px}.qvoice-record-stage{padding:16px 8px 12px}.qvoice-wave{gap:3px}.qvoice-wave i{width:2px}.qvoice-studio footer{flex-direction:column;gap:4px;margin-top:17px}.qvoice-auto{padding:12px}.qvoice-auto small{font-size:9px}.qvoice-dock{gap:7px;padding:9px 10px;border-radius:15px}.qvoice-dock-copy>span{max-width:38vw}.qvoice-dock .qvoice-text-button{font-size:10px;padding:4px}.qvoice-time{display:none}.qvoice-confirm{padding:8px}}
@media(prefers-reduced-motion:reduce){.qvoice-studio *,.qvoice-dock *{animation:none!important;transition:none!important}}
</style>
